mapper.select:
WITH T AS( SELECT ROW_NUMBER() OVER( ORDER BY cmmnty_chck_dt
ASC NULLS LAST DESC NULLS LAST
) AS row_num, cmmnty_sn, cmmnty_nm, tot_aceptnc_nmpr, cmmnty_opn_vwpoint, cmmnty_clos_vwpoint, resve_mxmm_nmpr, resve_mxmm_time, cmmnty_chcksttus, cmmnty_chck_dt FROM cmmnty WHERE 1 = 1
) SELECT T.cmmnty_sn, T.cmmnty_nm, T.cmmnty_chcksttus, T.cmmnty_chck_dt, T.cmmnty_opn_vwpoint, T.cmmnty_clos_vwpoint FROM T WHERE T.row_num BETWEEN (#{offset} + 1) AND (#{offset} + #{size})

mapper.update:
UPDATE CMMNTY 
SET CMMNTY_CHCKSTTUS = #{cmmntyChcksttus},
    CMMNTY_CHCK_DT = #{cmmntyChckDt}
WHERE CMMNTY_SN = #{cmmntySn}

mapper.select:
SELECT CMMNTY_SN, CMMNTY_NM, CMMNTY_CHCKSTTUS, CMMNTY_CHCK_DT
 FROM CMMNTY
WHERE CMMNTY_SN = #{cmmntySn}

SELECT COUNT(*)
FROM FCLTY_MANAGE
WHERE CMMNTY_SN = #{cmmntySn}

mapper.update:
UPDATE FCLTY_MANAGE A
SET A.FCLTYMANAGE_CHCKSTTUS = '점검완료'
WHERE A.FCLTY_MANAGE_SN IN (
  SELECT FCLTY_MANAGE_SN
  FROM FCLTY_MANAGE B
  WHERE B.CMMNTY_SN = #{cmmntySn}
  AND B.FCLTY_MANAGE_SN < (
      SELECT MAX(C.FCLTY_MANAGE_SN)
      FROM FCLTY_MANAGE C
      WHERE C.CMMNTY_SN = #{cmmntySn}
  )
)
